source = '''from collections import Counter, defaultdict


def _longest_regular_run(candidates, limit):
    candidates = sorted(candidates)
    best = []
    for step in range(1, limit + 1):
        by_residue = defaultdict(set)
        for p in candidates:
            by_residue[p % step].add(p)
        for values in by_residue.values():
            for start in values:
                if start - step not in values:
                    run = [start]
                    p = start + step
                    while p in values:
                        run.append(p)
                        p += step
                    if len(run) > len(best):
                        best = run
    return best


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_candidates = [r for r in range(h) if sum(v == bg for v in grid[r]) <= w // 2]
    col_candidates = [c for c in range(w) if sum(grid[r][c] == bg for r in range(h)) <= h // 2]
    rows = _longest_regular_run(row_candidates, h)
    cols = _longest_regular_run(col_candidates, w)

    intersections = {(r, c) for r in rows for c in cols}
    track_colors = []
    for r in rows:
        for c in range(w):
            if (r, c) not in intersections:
                track_colors.append(grid[r][c])
    for c in cols:
        for r in range(h):
            if (r, c) not in intersections:
                track_colors.append(grid[r][c])
    line_color = Counter(track_colors).most_common(1)[0][0]

    nodes = [[grid[r][c] for c in cols] for r in rows]
    marked_rows = [i for i, row in enumerate(nodes) if any(v != line_color for v in row)]
    marked_cols = [j for j in range(len(cols)) if any(nodes[i][j] != line_color for i in range(len(rows)))]
    r0, r1 = min(marked_rows), max(marked_rows)
    c0, c1 = min(marked_cols), max(marked_cols)
    out = []
    for i in range(r0, r1):
        row = []
        for j in range(c0, c1):
            corners = (nodes[i][j], nodes[i][j + 1], nodes[i + 1][j], nodes[i + 1][j + 1])
            if corners[0] != line_color and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                row.append(bg)
        out.append(row)
    return out
